/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. A number that has
 * left the project (moved away) is still retired, so the recorded high-water
 * mark is taken too.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const mark = getDb()
    .select({ value: projectIssueNumbers.lastNumber })
    .from(projectIssueNumbers)
    .where(
      and(
        orgPredicate(projectIssueNumbers.orgId, orgId),
        eq(projectIssueNumbers.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, mark?.value ?? 0) + 1;
}

/** Raises the project's high-water mark to `issueNumber`; it never lowers. */
function recordIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  getDb()
    .insert(projectIssueNumbers)
    .values({ orgId, projectId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: [projectIssueNumbers.orgId, projectIssueNumbers.projectId],
      set: {
        lastNumber: sql`max(${projectIssueNumbers.lastNumber}, excluded.last_number)`,
      },
    })
    .run();
}

