export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId,
      number: issueNumber,
      updatedAt: toIsoTimestamp(new Date()),
