import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe, resetEventBus } from "@/lib/event-bus";
import { registerActivityListeners } from "@/server/services/activity-service";
import { registerSearchListeners } from "@/server/services/search-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as issueService from "@/server/services/issue-service";
import { listActivity } from "@/server/services/activity-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;
let ops: Awaited<ReturnType<typeof projectRepo.insertProject>>;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("scratchmove");
  ops = await projectRepo.insertProject({
    orgId: tenant.org.id,
    name: "ops",
    slug: "ops",
    key: "OPS",
    description: null,
    visibility: "org",
    leadId: tenant.userIds.owner,
    color: "#6366f1",
    targetDate: null,
  });
  registerActivityListeners();
  registerSearchListeners();
});

afterAll(() => {
  resetEventBus();
  cleanup();
});

async function make(title: string, project = tenant.project) {
  const number = await issueRepo.nextIssueNumber(tenant.org.id, project.id);
  return issueRepo.insertIssue(
    issueInput(tenant.org.id, project.id, { title }),
    tenant.userIds.owner,
    number,
  );
}

describe("scratch: moveIssueToProject", () => {
  it("renumbers, retires the old number, keeps the source counter, emits once, audits under target", async () => {
    const a1 = await make("Alpha one");
    const a2 = await make("Alpha two");
    expect([a1.number, a2.number]).toEqual([1, 2]);

    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => {
      seen.push(p);
    });

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: a2.id,
      toProjectId: ops.id,
    });

    expect(moved.projectId).toBe(ops.id);
    expect(moved.number).toBe(1);
    expect(moved.title).toBe("Alpha two");
    expect(moved.authorId).toBe(a2.authorId);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: a2.id,
      fromProjectId: tenant.project.id,
      toProjectId: ops.id,
      fromNumber: 2,
      toNumber: 1,
    });

    // Source keeps 2 retired: next new issue there is 3.
    const next = await make("After move");
    expect(next.number).toBe(3);

    // Same-project move: nothing changes, nothing published.
    const again = await issueService.moveIssueToProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: moved.id,
      toProjectId: ops.id,
    });
    expect(again.number).toBe(1);
    expect(seen).toHaveLength(1);

    // Target next number is 2 now.
    const b = await make("Ops native", ops);
    expect(b.number).toBe(2);

    const page = await listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["issue.moved"],
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "issue.moved",
      subjectKind: "issue",
      subjectId: a2.id,
      projectId: ops.id,
      metadata: { fromProjectId: tenant.project.id, toProjectId: ops.id, fromNumber: 2, toNumber: 1 },
    });

    // Search follows the issue.
    const inOps = await searchRepo.searchDocuments({ orgId: tenant.org.id, q: "Alpha two", kinds: ["issue"], projectId: ops.id, limit: 25, cursor: null } as never);
    const inPlat = await searchRepo.searchDocuments({ orgId: tenant.org.id, q: "Alpha two", kinds: ["issue"], projectId: tenant.project.id, limit: 25, cursor: null } as never);
    expect(inOps.items.map((r) => r.subjectId)).toContain(a2.id);
    expect(inPlat.items.map((r) => r.subjectId)).not.toContain(a2.id);

    off();
  });

  it("refuses a viewer and changes nothing", async () => {
    const v = await make("Viewer target");
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => {
      seen.push(p);
    });
    await expect(
      issueService.moveIssueToProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: v.id,
        toProjectId: ops.id,
      }),
    ).rejects.toThrow();
    const reread = await issueRepo.findIssueById(tenant.org.id, v.id);
    expect(reread?.projectId).toBe(tenant.project.id);
    expect(seen).toHaveLength(0);
    off();
  });
});

